* Input source for AC and Transient
Vin vp 0 DC 0.9 AC 1 PULSE(0.4 1.4 10n 1n 1n 500n 1u)

.control
  * OP Analysis for Power
  op
  let power = -i(VDD) * 1.8
  print power

  * AC Analysis
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase = 180/PI * cph(v(Vout))

  meas ac open_loop_gain find gain_db at=10
  meas ac unity_gain_freq when gain_db=0 fall=1
  meas ac phase_margin find phase when gain_db=0 fall=1

  * Transient Analysis for Slew Rate
  tran 1n 2u
  meas tran t_rise trig v(Vout) val=0.6 rise=1 targ v(Vout) val=1.2 rise=1
  let slew_rate_rise = (1.2 - 0.6) / t_rise
  print slew_rate_rise

  meas tran t_fall trig v(Vout) val=1.2 fall=1 targ v(Vout) val=0.6 fall=1
  let slew_rate_fall = (1.2 - 0.6) / t_fall
  print slew_rate_fall

  quit
.endc
.end

